<?php require '../config/auth.php';require '../config/database.php';wajibAdmin();$id=(int)$_GET['id'];$q=$pdo->prepare('SELECT t.*,u.nama FROM transactions t JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$id]);$t=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT ti.*,p.nama FROM transaction_items ti JOIN products p ON p.id=ti.product_id WHERE ti.transaction_id=?');$q->execute([$id]);$items=$q->fetchAll(PDO::FETCH_ASSOC);?><!doctype html><html><head><meta charset="utf-8"><title>Invoice #<?=$id?></title><link rel="stylesheet" href="../assets/css/style.css"><style>@media print{button,a{display:none!important}}</style></head><body><div class="invoice"><h1>StyleKita</h1><h2>Invoice #<?=$id?></h2><p>Pelanggan: <?=$t['nama']?></p><?php foreach($items as $i):?><div class="tr"><span><?=$i['nama']?> × <?=$i['qty']?></span><b>Rp <?=number_format($i['harga']*$i['qty'],0,',','.')?></b></div><?php endforeach;?><h2>Total Rp <?=number_format($t['total'],0,',','.')?></h2><button class="btn" onclick="print()">Cetak</button></div></body></html>
